			/**
			 * 팝업 조건에 따라 CRUD 적용
			 * @param String psType
			 */
			function setCrud(psType){

			    if (psType == "UPDATE") {
			        util.Control.setVisible(app, false, ["btnDtlRevise", "btnDtlClose"]);  //수정, 닫기
			        util.Control.setVisible(app, true, ["btnDtlSave", "btnDtlCancel"]);  //저장, 취소
			        util.Control.setReadOnly(app, false, "grpData");
			        
			    } else { 
			        util.Control.setVisible(app, true, ["btnDtlRevise", "btnDtlClose"]);  //수정, 닫기
			        util.Control.setVisible(app, false, ["btnDtlSave", "btnDtlCancel"]);  //저장, 취소
			        util.Control.setReadOnly(app, true, "grpData");
			    }
			    
			}

			/**
			 * 팝업 조건에 따라 버튼 적용
			 * @param String psType
			 */
			function setRcpt(){
			    
			    var rcptSeCd = util.DataMap.getValue(app, "dmListParam", "RCPT_SE_CD");

			    if (rcptSeCd == "11" || rcptSeCd == "22") { //승인, 승인취소
			        util.Control.setVisible(app, true, ["btnAprv", "btnTransfer"]);  //승인, 타기관이송
			        util.Control.setVisible(app, false, ["btnAprvCancel"]);  //승인취소
			        util.Control.setVisible(app, true, ["btnDtlRevise"]);  //수정
			    } else if (rcptSeCd == "21") { //승인 
			        util.Control.setVisible(app, false, ["btnAprv", "btnTransfer"]);  //승인, 타기관이송
			        util.Control.setVisible(app, true, ["btnAprvCancel"]);  //승인취소
			        util.Control.setVisible(app, false, ["btnDtlRevise"]);  //수정
			    } else { //반려
			//        util.Control.setVisible(app, false, ["btnAprv", "btnAprvCancel", "btnRjct"]);  //승인, 승인취소, 반려
			//        util.Control.setVisible(app, false, ["btnDtlRevise"]);  //수정
			    }

			    
			}

