			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad(/* cpr.events.CEvent */ e){

			    var voInitValue = app.getAppProperty("data");
			    if (voInitValue == null) {
			       voInitValue = app.getHost().initValue;
			    }
			    
			    app.lookup("dsList").clearData();
			    setCrud();

			    util.Submit.send(app, 'subOnLoad', function(pbSuccess) {
			        if (pbSuccess) {
			            util.Msg.notify(app, "INF-M001");

			//            util.DataMap.setValue(app, "dmListParam", "TRPR_INFO_NO", voInitValue["RQST_TRPR_INFO_NO"]);
			            util.DataMap.setValue(app, "dmListParam", "TRPR_INFO_NO", voInitValue["RCPT_TRPR_INFO_NO"]);
			            util.DataMap.setValue(app, "dmListParam", "SRVC_PVSN_RQST_NO", voInitValue["SRVC_PVSN_RQST_NO"]);
			            util.DataMap.setValue(app, "dmListParam", "RCPT_SN", "1");
			            util.DataMap.setValue(app, "dmListParam", "RCPT_SE_CD", voInitValue["RCPT_SE_CD"]);
			            setRcpt();
			            doList();
			            
			            util.Control.redraw(app, "grpData");

			        }
			    });
			}

			/*
			 * "저장" 버튼(btnDtlSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnDtlSaveClick(/* cpr.events.CMouseEvent */ e){
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btnDtlSave = e.control;
			    var dsList = app.lookup("dsList");
			    
			    //센터배정오류 처리
			    if (dsList.getValue(0, "INTRVN_STTS_SE_CD") == "02" && 
			        dsList.getValue(0, "UNITVN_CS_SE_CD") == "05") {
			            dsList.setValue(0, "RCPT_SE_CD", "41");   //센터배정오류
			            var dmListParam = app.lookup("dmListParam");
			            dmListParam.setValue("RCPT_SE_CD", "41");
			    } else {
			        dsList.setValue(0, "RCPT_SE_CD", "00"); //저장
			    }
			    
			    doSave();
			    
			}

